await nav('items');await p.locator('#uiOpenDrawings').click();global.preDrawing=fp('02a-before-drawing-preview');await p.locator('#pilotBatchDrawingFiles').setInputFiles(['/tmp/r10/fixtures/U24-D16_A.pdf','/tmp/r10/fixtures/UAT24-SHAFT_A.pdf','/tmp/r10/fixtures/NO-MATCH_U24.pdf']);await p.locator('#pilotBatchDrawingAnalyze').click();await p.waitForTimeout(600);await tell('drawing match proposals',await p.locator('#pilotBatchDrawingPreview').innerText());await shot('03-drawing-match-candidates');await check('drawing preview leaves snapshot unchanged',fp('02b-after-drawing-preview'),preDrawing);await p.locator('#pilotBatchDrawingConfirm').click();await p.waitForTimeout(800);await save();global.drawn=fp('02c-drawing-confirmed');await check('only unique drawing associated',drawn.workspaces[wid].snapshot.state.items.map(x=>x.drawings?.length||0),[1,0,0]);await shot('03-drawing-confirmed');
