await nav('quoteImport');await p.locator('#quoteImportSupplier').selectOption('U24-A');await check('A confirmed edit disabled',await p.locator('[data-edit-quote="0"]').isDisabled(),true);await p.locator('#newQuoteRevision').click();await p.locator('#quoteEvidenceNote').fill('完全虚构 R10 A 同轮修订凭证');answers.push('9','10','1','quoted','虚构修订：价格9元');await p.locator('[data-edit-quote="0"]').click();await p.locator('#srmV31RevisionDiff').scrollIntoViewIfNeeded();await shot('V04-V2-draft-diff');await tell('V04 visible revision comparison',await p.locator('#srmV31RevisionDiff').innerText());await check('V04 same-round previous price',await p.locator('#quoteRoundBody tr').first().locator('td').nth(2).innerText(),'¥10.00');await check('V04 current effective price',await p.locator('#quoteRoundBody tr').first().locator('td').nth(4).innerText(),'¥9.00');await check('V04 change amount and percentage',await p.locator('#quoteRoundBody tr').first().locator('td').nth(5).innerText(),'-1.00 / -10.00%');await nav('quotes');await check('draft revision not used for quote',await p.locator('[data-award="RFQ-L00001|U24-A"] .quotePrice').innerText(),'¥10.00');await nav('quoteImport',false);await p.locator('#confirmQuoteRound').click();await save();global.rev=fp('04-revision-confirmed');await check('original confirmed V1 unchanged',rev.workspaces[wid].snapshot.state.quoteRounds.find(x=>x.supplierId==='U24-A'&&x.revisionNo===1),r1.workspaces[wid].snapshot.state.quoteRounds.find(x=>x.supplierId==='U24-A'&&x.revisionNo===1));await p.locator('#quoteRoundSelect').selectOption('1|1');await check('V1 UI price remains10',await p.locator('#quoteRoundBody tr').first().locator('td').nth(4).innerText(),'¥10.00');await shot('V04-original-V1-read-only');await p.locator('#quoteRoundSelect').selectOption('1|2');await p.locator('#srmV31RevisionDiff').scrollIntoViewIfNeeded();await shot('V04-V2-confirmed-diff');await nav('quotes');await p.locator('[data-common-supplier="U24-A"]').check();await p.locator('[data-common-supplier="U24-B"]').check();await check('V05 still no human awards after revision',(await decision())['人工已选'],'0');await p.locator('[data-award="RFQ-L00001|U24-B"]').click();await p.locator('#awardReasonConfirm').click();await check('nonlowest requires reason',await p.locator('#awardReasonModal').isVisible(),true);await shot('V05-empty-reason-rejected');await p.locator('#awardReasonInput').fill('虚构采购决策：乙方4天交付满足测试期限');await p.locator('#awardReasonConfirm').click();await check('V05 explicit nonlowest B counts one',(await decision())['人工已选'],'1');await shot('V05-one-human-choice');await p.locator('[data-award="RFQ-L00002|U24-B"]').click();await check('V05 manual tie selection counts two',(await decision())['人工已选'],'2');await check('V05 pending cleared',(await decision())['待人工决定'],'0');await save();await p.waitForTimeout(4200);global.awarded=fp('05-awarded');await tell('final decision',await decision());await tell('final comparison amounts',await p.locator('#quoteAnalysis').innerText());await shot('V05-two-human-decisions');

global.nav=async(id,side=true,page=p)=>{await page.locator(side?'[data-srm-v2-tab="'+id+'"]':(id==='settings'?'#uiFieldSettings':'.ui-workNav [data-tab="'+id+'"]')).click();await check('navigation '+id,{side:await page.locator('.srm-v2-sideitem[aria-current="page"]').getAttribute('data-srm-v2-tab'),tab:await page.locator('.tab.active').first().getAttribute('data-tab'),panel:await page.locator('section.panel.active').getAttribute('id')},{side:id,tab:id,panel:id})};
await nav('items');for(const id of ['#uiProjectDetails','#uiSupplierTools','#uiDataTools','#uiDrawingTools'])if(await p.locator(id).evaluate(e=>e.open))await p.locator(id+' > summary').click();global.geometry=[];
for(const [width,height]of [[1024,768],[1366,768],[1600,900]]){
 await p.setViewportSize({width,height});await p.locator('[data-srm-v2-action="project"]').click();await p.waitForTimeout(400);await p.evaluate(()=>window.scrollTo({top:0,behavior:'instant'}));await shot('prod-'+width+'-projects');await tell(width+' project drawer geometry',await p.locator('#pilotControls details').evaluateAll(es=>es.map(e=>({id:e.id,open:e.open,height:e.getBoundingClientRect().height,summaryHeight:e.querySelector('summary')?.getBoundingClientRect().height}))));await p.locator('#uiProjectDetails > summary').click();
 for(const id of ['items','assign','quoteImport','quotes','settings']){
  await nav(id);if(id==='assign'){await p.locator('.modebtn[data-mode="supplierFirst"]').click();await p.locator('[data-sf-s="U24-B"]').click()}
  await p.waitForTimeout(400);await p.evaluate(()=>window.scrollTo({top:0,behavior:'instant'}));await p.waitForTimeout(100);let g=await p.evaluate(()=>{let rect=s=>{let e=document.querySelector(s);if(!e)return null;let r=e.getBoundingClientRect();return{x:r.x,y:r.y,right:r.right,bottom:r.bottom,width:r.width,height:r.height}};return{scrollX,scrollY,documentWidth:document.documentElement.scrollWidth,viewport:innerWidth,height:innerHeight,bg:getComputedStyle(document.body).backgroundColor,sidebar:rect('.srm-v2-sidebar'),panel:rect('section.panel.active'),intro:rect('section.panel.active .srm-v3-pageIntro'),firstRow:rect('section.panel.active tbody tr')}});geometry.push({page:id,width,height,...g});await check(width+' '+id+' no document overflow',g.documentWidth<=width,true);await check(width+' '+id+' sidebar clear',g.panel.x>=g.sidebar.right,true);await shot('prod-'+width+'-'+id);if(id==='items'){await check(width+' V01 title visible and sized',g.intro&&g.intro.height>0,true)}if(id==='assign'){await tell(width+' V03 layout',await p.locator('#supplierFirstBoard').count());await check(width+' V03 quantities and relations shown',(await p.locator('#sfItemBody').innerText()).includes('25')&&(await p.locator('#sfItemBody').innerText()).includes('虚构甲方'),true)}
  if(id==='assign'){await p.locator('.modebtn[data-mode="itemFirst"]').click();await p.evaluate(()=>window.scrollTo({top:0,behavior:'instant'}));await shot('prod-'+width+'-assign-item')}
  if(id==='quoteImport'){await p.locator('#confirmQuoteRound').scrollIntoViewIfNeeded();await p.locator('#confirmQuoteRound').hover();await shot('P3-fixed-'+width);let v=await p.locator('#confirmQuoteRound').evaluate(e=>({disabled:e.disabled,background:getComputedStyle(e).backgroundColor,cursor:getComputedStyle(e).cursor,title:e.title}));await check(width+' disabled confirmation grey and nonpointer',[v.disabled,v.background,v.cursor],[true,'rgb(232, 237, 243)','not-allowed']);await check(width+' locked hint visible',await p.locator('#srmV3QuoteLockHint').isVisible(),true);await tell(width+' lock hint',await p.locator('#srmV3QuoteLockHint').innerText());await p.locator('#quoteRoundBody').scrollIntoViewIfNeeded();await p.locator('#quoteRoundBody').hover();await p.mouse.wheel(2000,0);await p.waitForTimeout(150);await shot('prod-'+width+'-quote-right')}
 }
}
fs.writeFileSync(root+'product-geometry.json',JSON.stringify(geometry,null,2));await check('parity UI navigation does not change business',fp('06-after-parity'),awarded);await p.setViewportSize({width:1366,height:768});await nav('quoteImport');await p.locator('#quoteRoundSelect').selectOption('1|1');await tell('original history UI',await p.locator('#quoteRoundBody').innerText());await shot('history-original-V1');await p.locator('#quoteRoundSelect').selectOption('1|2');await p.locator('#quoteRoundBody').scrollIntoViewIfNeeded();await shot('revision-V2-table');await tell('same-round V2 actual columns',await p.locator('#quoteRoundBody').innerText());await nav('quotes');
